// Horizon Chart — Time Series, route: jsx
// Source: horizon-chart_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useId, useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from horizon ----
// Synthetic daily traffic counts for 8 named locations, standing in for the notebook's
// traffic.csv. A seeded LCG (same recipe as realtimeHorizon.ts) keeps every render identical.
const SEED_BASE = 4021;
const DAY_MS = 86400000;
const START = Date.UTC(2024, 0, 1);
const DAYS = 120;

const LOCATION_NAMES = [
  'Bridge St',
  'Canal Rd',
  'Harbor Ave',
  'Mill Ln',
  'Oak Park',
  'Pine Cross',
  'River Walk',
  'Station Sq'
];

const advance = (seed: number) => (seed * 1664525 + 1013904223) >>> 0;

type HorizonPoint = { date: Date; value: number };
type HorizonSeries = { name: string; values: HorizonPoint[] };

const horizonSeries: HorizonSeries[] = LOCATION_NAMES.map((name, i) => {
  let seed = SEED_BASE + i * 97;
  const baseline = 40 + i * 15;
  const values: HorizonPoint[] = [];
  for (let day = 0; day < DAYS; day++) {
    seed = advance(seed);
    const noise = (seed / 4294967296 - 0.5) * 12;
    const weekday = new Date(START + day * DAY_MS).getUTCDay();
    const weekendDip = weekday === 0 || weekday === 6 ? -0.35 : 0;
    const seasonal = 10 * Math.sin((day / DAYS) * Math.PI * 2);
    const value = Math.max(0, baseline * (1 + weekendDip) + seasonal + noise);
    values.push({ date: new Date(START + day * DAY_MS), value });
  }
  return { name, values };
});

const MARGIN = { top: 28, right: 16, bottom: 8, left: 84 };
const BANDS = 4;
const GAP = 2;

// Reversed so the darkest step reads as the highest fold, lightest as the lowest.
const bandColors = [...d3.schemeBlues[BANDS + 1]].reverse().slice(0, BANDS);

/** One row per series; every series shares one x domain and one value scale. */
export type Data = { name: string; values: { date: Date; value: number }[] }[];

export default function HorizonChart({ data = horizonSeries, width }:
  { data?: Data; width: number }) {
  const step = Math.max(16, Math.min(24, Math.round(width / 45)));
  const trackHeight = data.length * (step + GAP) - GAP;
  const height = MARGIN.top + trackHeight + MARGIN.bottom;
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);
  const clipBase = `horizon-row-${useId().replace(/:/g, '')}`;

  const x = useMemo(() => {
    const allDates = data.flatMap((s) => s.values.map((d) => d.date));
    return d3.scaleUtc().domain(d3.extent(allDates) as [Date, Date]).range([0, innerWidth]);
  }, [data, innerWidth]);

  const area = useMemo(() => {
    const maxValue = d3.max(data.flatMap((s) => s.values.map((d) => d.value))) ?? 1;
    const y = d3.scaleLinear().domain([0, maxValue]).range([0, -BANDS * step]);
    return d3
      .area<{ date: Date; value: number }>()
      .x((d) => x(d.date))
      .y0(0)
      .y1((d) => y(d.value));
  }, [data, x, step]);

  const paths = useMemo(
    () => data.map((s) => area(s.values) ?? ''),
    [data, area]
  );

  const xTicks = useMemo(() => {
    const format = d3.utcFormat('%b %d');
    return x.ticks(Math.max(2, Math.round(innerWidth / 90))).map((d) => ({
      value: format(d),
      offset: x(d)
    }));
  }, [x, innerWidth]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Horizon chart: daily traffic counts for ${data.length} locations over ${data[0].values.length} days, each series folded into ${BANDS} colour bands so full magnitude fits a compact row. Synthetic data from a seeded generator, not real traffic counts.`}
    >
      <defs>
        {data.map((_, i) => (
          <clipPath key={i} id={`${clipBase}-${i}`}>
            <rect x={0} y={0} width={innerWidth} height={step} />
          </clipPath>
        ))}
      </defs>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          <line x1={0} x2={innerWidth} y1={0} y2={0} />
          {xTicks.map(({ value, offset }) => (
            <g key={value} transform={`translate(${offset},0)`}>
              <line y1={0} y2={-5} />
              <text y={-8} textAnchor="middle">
                {value}
              </text>
            </g>
          ))}
        </g>

        {data.map((s, i) => (
          <g key={s.name} transform={`translate(0,${i * (step + GAP)})`}>
            <rect width={innerWidth} height={step} fill="var(--bg)" />
            <g clipPath={`url(#${clipBase}-${i})`}>
              {bandColors.map((fill, band) => (
                <path
                  key={band}
                  d={paths[i]}
                  fill={fill}
                  transform={`translate(0,${(band + 1) * step})`}
                />
              ))}
            </g>
            <text
              x={-8}
              y={step / 2}
              dy="0.32em"
              textAnchor="end"
              fill="var(--muted)"
              fontSize={Math.min(11, step * 0.5)}
            >
              {s.name}
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
